/*
 * Shared by the HUD library simulator programs (test_hud.c, test_hud_draw.c), each including it once:
 * the mock register block of fw.S, a bump heap behind the malloc mock, the layer-1 buffers and GUI
 * words as plain memory, and the dump output. images.c (generated by test_hud_sim.py from the stock
 * firmware) holds the image table.
 */
#ifndef _SIM_HUD_H
#define _SIM_HUD_H

#include <hud.h>

#define SIM_U8(a) (*(volatile uint8_t *)(a))
#define SIM_U16(a) (*(volatile uint16_t *)(a))
#define SIM_U32(a) (*(volatile uint32_t *)(a))

#define SIM_PITCH 896
#define SIM_BUF0 0xA0800000u
#define SIM_BUF1 0xA0900000u
#define SIM_GUI 0x33		/* what the "GUI" painted */

#define SIM_VRAM_TABLE 0x6066ED88u
#define SIM_VRAM0 0x6066E100u
#define SIM_FONT_RES 0x6066EDACu
#define SIM_IMAGE_TABLE 0xAF966010u
#define SIM_LAYER_BPP 0x6F1232C8u
#define SIM_DRAW_BUF 0x6034D5B4u
#define SIM_HIDE_MASK 0x6034D5D0u
#define SIM_ONE_MODE 0x6034D5D2u
#define SIM_ONE_LAYER 0x6034D5D4u
#define SIM_ONE_BUF 0x6034D5D6u
#define SIM_SUPER 0x60702278u
#define SIM_STATE 0x60702279u

extern const void *const sim_images[];		/* images.c: [id] -> struct gui_image */

uint32_t sim_exit_code = 99;
volatile uint32_t mreg[5];
static uint8_t sim_heap[0x10000] __attribute__((aligned(4)));
static unsigned int sim_heap_used;

void sim_write(const void *buf, unsigned int len);

uint32_t c_malloc(void)
{
	unsigned int size = (mreg[2] + 3) & ~3u;

	if (sim_heap_used + size > sizeof(sim_heap))
		return 0;
	sim_heap_used += size;
	return (uint32_t)&sim_heap[sim_heap_used - size];
}

uint32_t c_free(void)
{
	return 0;
}

static volatile uint8_t *sim_px(uint32_t buf, const struct fenykl_hud_elem *e, int r, int c)
{
	return (volatile uint8_t *)(buf + (e->y + r) * SIM_PITCH + e->x + c);
}

static void sim_fill(uint32_t buf, const struct fenykl_hud_elem *e, uint8_t v)
{
	for (int r = 0; r < e->h; r++)
		for (int c = 0; c < e->w; c++)
			*sim_px(buf, e, r, c) = v;
}

/* 1 if the rectangle in buf is all v */
static int sim_all(uint32_t buf, const struct fenykl_hud_elem *e, uint8_t v)
{
	for (int r = 0; r < e->h; r++)
		for (int c = 0; c < e->w; c++)
			if (*sim_px(buf, e, r, c) != v)
				return 0;
	return 1;
}

/* 1 if the rectangle is the same in both buffers */
static int sim_same(const struct fenykl_hud_elem *e)
{
	for (int r = 0; r < e->h; r++)
		for (int c = 0; c < e->w; c++)
			if (*sim_px(SIM_BUF0, e, r, c) != *sim_px(SIM_BUF1, e, r, c))
				return 0;
	return 1;
}

static char *sim_dec(char *o, int v)
{
	char s[12];
	int n = 0;

	if (v < 0)
		*o++ = '-', v = -v;
	do
		s[n++] = (char)('0' + v % 10);
	while ((v /= 10));
	while (n)
		*o++ = s[--n];
	*o++ = ' ';
	return o;
}

/* Two layer-1 buffers, the image table, Basic screen (0x03), nothing masked; no font. */
static void sim_setup_memory(void)
{
	SIM_U32(SIM_VRAM0) = 2;			/* plane */
	SIM_U16(SIM_VRAM0 + 4) = SIM_PITCH;
	SIM_U16(SIM_VRAM0 + 6) = 600;
	SIM_U32(SIM_VRAM0 + 8) = SIM_BUF0;
	SIM_U32(SIM_VRAM0 + 16) = 2;
	SIM_U16(SIM_VRAM0 + 20) = SIM_PITCH;
	SIM_U16(SIM_VRAM0 + 22) = 600;
	SIM_U32(SIM_VRAM0 + 24) = SIM_BUF1;
	SIM_U32(SIM_VRAM_TABLE + 8) = SIM_VRAM0;
	SIM_U32(SIM_VRAM_TABLE + 12) = SIM_VRAM0 + 16;
	SIM_U32(SIM_IMAGE_TABLE) = (uint32_t)sim_images;
	SIM_U8(SIM_LAYER_BPP + 1) = 8;
	SIM_U8(SIM_DRAW_BUF) = 0;
	SIM_U16(SIM_HIDE_MASK) = 0;
	SIM_U8(SIM_ONE_MODE) = 0;
	SIM_U8(SIM_SUPER) = 0x02;
	SIM_U8(SIM_STATE) = 0x03;
}

#endif
